CREATE OR REPLACE FUNCTION public.photo_training_class_valid(s text,c text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT s IN ('shingle','clay_tile','concrete_tile','metal','flat','envelope') AND (c=ANY(ARRAY['normal_flashing_transition','normal_penetration','normal_repair','normal_shadow','normal_material_variation','maintenance_debris','maintenance_vegetation','maintenance_staining','maintenance_blocked_drainage','uncertain_close_up_required','not_assessable_obstruction','not_assessable_resolution','not_assessable_glare']) OR CASE s WHEN 'shingle' THEN c=ANY(ARRAY['normal_shingle_courses','normal_granule_texture','normal_visible_sealant_strip','normal_ridge_cap','missing_shingles','displaced_shingles','creased_shingles','torn_shingles','exposed_underlayment','ridge_cap_loss','missing_tab']) WHEN 'clay_tile' THEN c=ANY(ARRAY['normal_tile_alignment','normal_tile_overlap','normal_intact_ridge_tile','cracked_tile','broken_tile','displaced_tile','missing_tile','ridge_tile_damage','exposed_underlayment','fractured_tile','slipped_tile','deteriorated_mortar']) WHEN 'concrete_tile' THEN c=ANY(ARRAY['normal_tile_alignment','normal_tile_overlap','normal_intact_ridge_tile','cracked_tile','broken_tile','displaced_tile','missing_tile','ridge_tile_damage','exposed_underlayment','fractured_tile','slipped_tile','deteriorated_mortar']) WHEN 'metal' THEN c=ANY(ARRAY['normal_panel','normal_seam','normal_fastener_pattern','displaced_panel','open_seam','loose_flashing','panel_deformation','missing_component','corrosion','visible_dent']) WHEN 'flat' THEN c=ANY(ARRAY['normal_membrane_lap','normal_seam','normal_drain','membrane_tear','membrane_puncture','open_seam','displaced_flashing','membrane_blister','exposed_substrate','ponding_evidence','deteriorated_sealant']) WHEN 'envelope' THEN c=ANY(ARRAY['normal_siding','normal_house_wrap','normal_sheathing','normal_fascia','normal_soffit','normal_gutter','normal_vent','missing_siding','torn_house_wrap','exposed_sheathing','damaged_fascia','damaged_soffit','damaged_flashing','visible_deterioration','damaged_gutter']) ELSE false END) $$;
REVOKE ALL ON FUNCTION public.photo_training_class_valid(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.photo_training_class_valid(text,text) TO authenticated,service_role;